// data.paged_sql — SQL-level paged asset reads (conv-26) against the frozen
// Python oracle. Replays the committed fixtures/catalog_gc/paged_queries
// scenario (generated by tools/oracle/generate_catalog_gc_fixtures.py from
// the real DataCatalogService, whose paged path routes through
// CatalogIndex.search_assets_page) straight over catalog.sqlite:
//
//   1. every frozen query must reproduce its frozen rows + count through
//      search_assets_page_sql / count_assets_sql WITHOUT loading the
//      document (the v6 lazy-browse contract), and
//   2. the SQL path and the document path (entity_view.hpp) must agree
//      row-for-row on the same store — the two faces of the parity contract.
#include "pwb_test.hpp"
#include "compare_json.hpp"

#include "pwb/catalog/entity_view.hpp"
#include "pwb/catalog/models.hpp"
#include "pwb/catalog/paged_sql.hpp"
#include "pwb/catalog/repository.hpp"
#include "pwb/catalog/sqlite.hpp"
#include "pwb/domain/json.hpp"
#include "pwb/project/paths.hpp"

#include <filesystem>
#include <fstream>
#include <sstream>
#include <string>
#include <vector>

namespace {

namespace fs = std::filesystem;
using pwb::catalog::EntityPageQuery;
using pwb::domain::Json;

fs::path scenario_dir() {
    return fs::path(PWB_DATA_FIXTURE_DIR) / "catalog_gc" / "paged_queries";
}

Json load_json(const fs::path& file) {
    std::ifstream stream(file, std::ios::binary);
    std::ostringstream buffer;
    buffer << stream.rdbuf();
    return Json::parse(buffer.str(), nullptr, false);
}

struct Scratch {
    fs::path root;

    Scratch() {
        root = fs::temp_directory_path() / "pwb_paged_sql_replay";
        std::error_code ec;
        fs::remove_all(root, ec);
        fs::create_directories(root, ec);
        fs::copy(scenario_dir() / "tree", root,
                 fs::copy_options::recursive
                     | fs::copy_options::overwrite_existing,
                 ec);
    }

    ~Scratch() {
        std::error_code ec;
        fs::remove_all(root, ec);
    }
};

EntityPageQuery query_from_spec(const Json& spec) {
    EntityPageQuery query;
    if (spec.contains("text")) {
        query.text = spec["text"].get<std::string>();
    }
    if (spec.contains("stage")) {
        query.stage = spec["stage"].get<std::string>();
    }
    if (spec.contains("tags")) {
        for (const auto& tag : spec["tags"]) {
            query.tags.push_back(tag.get<std::string>());
        }
    }
    if (spec.contains("tag_op")) {
        query.tag_op = spec["tag_op"].get<std::string>();
    }
    // `type: ""` is a PRESENT empty filter in Python (matches nothing), not
    // an absent one — keep the distinction when mapping to the optional.
    if (spec.contains("type")) {
        query.type = spec["type"].get<std::string>();
    }
    if (spec.contains("asset_id")) {
        query.asset_id = spec["asset_id"].get<std::string>();
    }
    if (spec.contains("asset_ids")) {
        for (const auto& id : spec["asset_ids"]) {
            query.asset_ids.push_back(id.get<std::string>());
        }
    }
    if (spec.contains("include_trashed")) {
        query.include_trashed = spec["include_trashed"].get<bool>();
    }
    if (spec.contains("trashed_only")) {
        query.trashed_only = spec["trashed_only"].get<bool>();
    }
    if (spec.contains("order_by")) {
        query.order_by = spec["order_by"].get<std::string>();
    }
    if (spec.contains("limit")) {
        query.limit = spec["limit"].get<std::int64_t>();
    }
    if (spec.contains("offset")) {
        query.offset = spec["offset"].get<std::int64_t>();
    }
    if (spec.contains("after")) {
        query.after = {spec["after"][0].get<std::string>(),
                       spec["after"][1].get<std::string>()};
    }
    return query;
}

// The metadata row field is a JSON TEXT column; Python freezes it parsed
// (conv-15 decisions D7). Same rule as the document-path replay.
bool row_matches(const Json& expected, const Json& actual, std::string* diff) {
    if (auto result = pwb_test::json_compare(expected, actual, "$")) {
        *diff = *result;
        return false;
    }
    return true;
}

}  // namespace

PWB_TEST(sql_pages_replay_the_frozen_python_matrix) {
    Scratch scratch;
    const Json oracle = load_json(scenario_dir() / "oracle.json");
    PWB_CHECK(oracle.contains("queries"));
    int compared_rows = 0;

    auto opened = pwb::catalog::Database::open(
        pwb::project::catalog_sqlite_for(scratch.root / "demo.paleo.json"),
        pwb::catalog::SqliteOpenMode::ReadOnly);
    PWB_CHECK(opened.is_ok());
    pwb::catalog::Database& db = opened.value();

    for (const auto& entry : oracle["queries"]) {
        const std::string name = entry["name"].get<std::string>();
        const EntityPageQuery query = query_from_spec(entry["query"]);
        const std::vector<Json> rows =
            pwb::catalog::search_assets_page_sql(db, query);
        const std::int64_t count = pwb::catalog::count_assets_sql(db, query);

        if (auto diff_row_count = pwb_test::json_compare(
                Json(static_cast<std::int64_t>(rows.size())),
                Json(static_cast<std::int64_t>(
                    entry["rows"].size())),
                "$.rows.length")) {
            std::cout << "  FAIL [" << name << "] row count "
                      << rows.size() << " != " << entry["rows"].size()
                      << "\n";
            PWB_CHECK(false);
        }
        for (std::size_t i = 0; i < rows.size(); ++i) {
            // Both sides serialize metadata as text; parse the actual one so
            // the comparison is semantic (key sets + values), not byte-wise.
            Json actual = rows[i];
            if (actual.contains("metadata") &&
                actual["metadata"].is_string()) {
                Json parsed = Json::parse(
                    actual["metadata"].get<std::string>(), nullptr, false);
                if (!parsed.is_discarded()) actual["metadata"] = parsed;
            }
            Json expected = entry["rows"][i];
            if (expected.contains("metadata") &&
                expected["metadata"].is_string()) {
                Json parsed = Json::parse(
                    expected["metadata"].get<std::string>(), nullptr, false);
                if (!parsed.is_discarded()) expected["metadata"] = parsed;
            }
            std::string diff;
            if (!row_matches(expected, actual, &diff)) {
                std::cout << "  FAIL [" << name << "] row " << i << ": "
                          << diff << "\n    expected: " << expected.dump()
                          << "\n    actual:   " << actual.dump() << "\n";
                PWB_CHECK(false);
            }
            ++compared_rows;
        }
        if (count != entry["count"].get<std::int64_t>()) {
            std::cout << "  FAIL [" << name << "] count " << count
                      << " != " << entry["count"].get<std::int64_t>()
                      << "\n";
            PWB_CHECK(false);
        }
    }
    std::cout << "  compared " << compared_rows << " rows across "
              << oracle["queries"].size() << " frozen queries\n";
    PWB_CHECK(compared_rows > 50);
}

PWB_TEST(sql_path_and_document_path_agree) {
    Scratch scratch;
    pwb::catalog::CatalogRepository repository(
        pwb::project::catalog_sqlite_for(scratch.root / "demo.paleo.json"));
    auto document_result = repository.open_read_only();
    PWB_CHECK(document_result.is_ok());
    const pwb::catalog::CatalogDocument& document = document_result.value();

    auto opened = pwb::catalog::Database::open(
        pwb::project::catalog_sqlite_for(scratch.root / "demo.paleo.json"),
        pwb::catalog::SqliteOpenMode::ReadOnly);
    PWB_CHECK(opened.is_ok());

    const Json oracle = load_json(scenario_dir() / "oracle.json");
    for (const auto& entry : oracle["queries"]) {
        const std::string name = entry["name"].get<std::string>();
        const EntityPageQuery query = query_from_spec(entry["query"]);
        const std::vector<Json> sql_rows =
            pwb::catalog::search_assets_page_sql(opened.value(), query);
        const std::vector<Json> doc_rows =
            pwb::catalog::search_assets_page(document, query);
        if (sql_rows.size() != doc_rows.size()) {
            std::cout << "  FAIL [" << name << "] path sizes "
                      << sql_rows.size() << " vs " << doc_rows.size()
                      << "\n";
            PWB_CHECK(false);
            continue;
        }
        for (std::size_t i = 0; i < sql_rows.size(); ++i) {
            if (auto diff = pwb_test::json_compare(doc_rows[i], sql_rows[i],
                                                   "$")) {
                std::cout << "  FAIL [" << name << "] row " << i
                          << " doc-vs-sql: " << *diff << "\n";
                PWB_CHECK(false);
            }
        }
    }
}

PWB_TEST(sql_keyset_deep_page_is_stable) {
    // Walk the whole fixture with the (name, id) cursor in limit-3 pages and
    // require the concatenation to equal the single full page — the
    // no-offset deep-paging contract.
    Scratch scratch;
    auto opened = pwb::catalog::Database::open(
        pwb::project::catalog_sqlite_for(scratch.root / "demo.paleo.json"),
        pwb::catalog::SqliteOpenMode::ReadOnly);
    PWB_CHECK(opened.is_ok());

    EntityPageQuery full;
    full.limit = 500;
    const std::vector<Json> all_rows =
        pwb::catalog::search_assets_page_sql(opened.value(), full);
    PWB_CHECK(all_rows.size() > 6);

    std::vector<Json> walked;
    EntityPageQuery page;
    page.limit = 3;
    int guard = 0;
    while (true) {
        const std::vector<Json> rows =
            pwb::catalog::search_assets_page_sql(opened.value(), page);
        if (rows.empty()) break;
        walked.insert(walked.end(), rows.begin(), rows.end());
        page.after = {rows.back()["name"].get<std::string>(),
                      rows.back()["id"].get<std::string>()};
        PWB_CHECK(++guard < 100);
    }
    PWB_CHECK(walked.size() == all_rows.size());
    for (std::size_t i = 0; i < walked.size(); ++i) {
        if (auto diff = pwb_test::json_compare(all_rows[i], walked[i], "$")) {
            std::cout << "  FAIL keyset walk row " << i << ": " << *diff
                      << "\n";
            PWB_CHECK(false);
        }
    }
}
